const payload = $json.body ?? $json;

const imageUrls = Array.isArray(payload.imageUrls) ? payload.imageUrls : [];

const moderationPrompt = `
Ban la AI moderation assistant cho nen tang CafeStory.

Hay phan tich noi dung bi user report.

Quy tac:
- Chi tra ve JSON hop le, khong markdown.
- Khong tu xoa noi dung.
- Phan biet review tieu cuc hop le voi noi dung vi pham.
- SAFE: noi dung an toan hoac report co ve sai.
- NEEDS_REVIEW: chua chac chan, can admin xem.
- VIOLATION: vi pham ro rang.

Report:
- targetType: ${payload.targetType}
- reason: ${payload.reason ?? ""}
- description: ${payload.description ?? ""}

Noi dung:
${payload.content ?? ""}

Image URLs:
${imageUrls.join("\n")}

JSON schema bat buoc:
{
  "decision": "SAFE | NEEDS_REVIEW | VIOLATION",
  "score": 0.0,
  "labels": ["SPAM"],
  "explanation": "Giai thich ngan gon bang tieng Viet"
}
`;

return [
  {
    json: {
      originalPayload: payload,
      geminiRequest: {
        contents: [
          {
            role: "user",
            parts: [
              {
                text: moderationPrompt
              }
            ]
          }
        ],
        generationConfig: {
          temperature: 0.1,
          responseMimeType: "application/json"
        }
      }
    }
  }
];

function cleanJsonText(text) {
  return String(text ?? "")
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();
}

const candidateText = $json.candidates?.[0]?.content?.parts?.[0]?.text;

let parsed;
try {
  parsed = JSON.parse(cleanJsonText(candidateText));
} catch (error) {
  parsed = {
    decision: "NEEDS_REVIEW",
    score: 0.0,
    labels: ["AI_PARSE_ERROR"],
    explanation: "Gemini tra ve response khong dung JSON schema."
  };
}

const allowedDecisions = ["SAFE", "NEEDS_REVIEW", "VIOLATION"];
const decision = allowedDecisions.includes(parsed.decision)
  ? parsed.decision
  : "NEEDS_REVIEW";

const rawScore = Number(parsed.score);
const score = Number.isFinite(rawScore)
  ? Math.max(0, Math.min(1, rawScore))
  : 0.0;

const labels = Array.isArray(parsed.labels) && parsed.labels.length > 0
  ? parsed.labels.map(String)
  : [decision];

return [
  {
    json: {
      decision,
      score,
      labels,
      explanation: parsed.explanation || "Khong co giai thich tu Gemini.",
      modelName: $env.GEMINI_MODEL || "gemini-2.0-flash"
    }
  }
];
